<template>
  <div class="pipeline-why" data-test="pipeline-why-blocked">
    <!-- The one sentence. Built server-side from a closed vocabulary. -->
    <p class="pipeline-why__sentence" data-test="pipeline-why-sentence">
      {{ sentence }}
    </p>

    <div
      v-if="blockingStage"
      class="pipeline-why__stage"
      data-test="pipeline-why-stage"
    >
      <span class="pipeline-why__stage-no">{{ blockingStage.no }}</span>
      <span class="pipeline-why__stage-label">{{ stageLabel }}</span>
      <q-chip
        v-if="blockingStage.reason_code"
        dense
        square
        outline
        :label="reasonLabel"
        data-test="pipeline-why-reason"
      />
      <q-chip
        v-if="blockingStage.source"
        dense
        square
        outline
        :label="blockingStage.source"
        data-test="pipeline-why-source"
      />
      <q-chip
        v-if="durationLabel"
        dense
        square
        outline
        :label="durationLabel"
        data-test="pipeline-why-duration"
      />
    </div>

    <!-- Stage-specific evidence, or an honest statement that there is none. -->
    <div class="pipeline-why__section">
      <div class="pipeline-why__heading">
        {{ $t('pipeline_why_evidence_heading') }}
      </div>

      <dl
        v-if="evidenceRows.length"
        class="pipeline-why__kv"
        data-test="pipeline-why-evidence"
      >
        <template v-for="row in evidenceRows" :key="row.key">
          <dt>{{ row.label }}</dt>
          <dd :data-test="`pipeline-why-evidence-${row.key}`">
            {{ row.value }}
          </dd>
        </template>
      </dl>

      <!--
        The honest gap. An absent evidence block is NOT "nothing was wrong
        here" — it is "the hook that writes this stage does not record a
        diagnosis yet", and the reader is told which fields are missing so the
        gap is actionable instead of mysterious.
      -->
      <div
        v-else
        class="pipeline-why__missing"
        data-test="pipeline-why-evidence-missing"
      >
        <q-icon name="help_outline" size="16px" />
        <span>{{ missingEvidenceText }}</span>
      </div>

      <div
        v-if="missingFields.length"
        class="pipeline-why__missing-fields"
        data-test="pipeline-why-evidence-expected"
      >
        {{ $t('pipeline_why_evidence_expected') }}: {{ missingFields.join(', ') }}
      </div>
    </div>

    <!--
      The analysis. Four questions when a model wrote it, one when a rule did.
      The header always discloses which, because a page that shows model text
      has to say so.
    -->
    <div v-if="analysis" class="pipeline-why__section">
      <div class="pipeline-why__heading">
        <span>{{ $t('pipeline_why_analysis_heading') }}</span>
        <q-chip
          dense
          square
          :color="isAiAnalysis ? 'primary' : 'grey-6'"
          text-color="white"
          :label="
            isAiAnalysis
              ? $t('pipeline_why_source_ai')
              : $t('pipeline_why_source_deterministic')
          "
          data-test="pipeline-why-analysis-source"
        />
      </div>

      <dl class="pipeline-why__kv" data-test="pipeline-why-analysis">
        <template v-for="question in analysisRows" :key="question.key">
          <dt>{{ question.label }}</dt>
          <dd :data-test="`pipeline-why-analysis-${question.key}`">
            {{ question.value }}
          </dd>
        </template>
      </dl>

      <p
        v-if="!isAiAnalysis"
        class="pipeline-why__note"
        data-test="pipeline-why-analysis-note"
      >
        {{ deterministicNote }}
      </p>
    </div>
  </div>
</template>

<script lang="ts">
import { computed, defineComponent, inject, type PropType } from 'vue';
import { useTolgee } from '@tolgee/vue';
import type {
  PipelineAnalysis,
  PipelineStage,
  PipelineText,
} from 'src/services/analytics/PipelineExplanationService';
import { pickText } from 'src/services/analytics/PipelineExplanationService';

/**
 * „Dieses Dokument blieb in Stufe X hängen, weil …" — the plain-language half
 * of the pipeline diagram (DOCB-14351).
 *
 * Three blocks, in the order a reader asks for them: the sentence, the
 * stage-specific evidence, and the analysis.
 *
 * Two of them can be absent, and BOTH say so rather than disappearing:
 *
 * * no evidence -> the producing hook does not record a diagnosis yet. Shown
 *   with the reason and the list of fields it is waiting for, because "we do
 *   not collect this" and "there was nothing to collect" are different
 *   statements and only one of them is true here.
 * * no model -> the analysis carries one rule-based paragraph and says
 *   `deterministic`. The other three questions stay empty instead of being
 *   filled with something that reads like an answer.
 *
 * Every sentence in `explanation`, `summary` and `analysis` arrives BILINGUAL
 * from the API — composed there from a closed vocabulary — so this component
 * picks a language rather than translating. Only its own chrome (headings,
 * the source chip) goes through Tolgee.
 */
export default defineComponent({
  name: 'PipelineWhyBlocked',

  props: {
    /** The bilingual sentence from the envelope. */
    explanation: {
      type: Object as PropType<PipelineText | null>,
      default: null,
    },
    /** The stage the document (or the cluster) stopped at, if any. */
    blockingStage: {
      type: Object as PropType<PipelineStage | null>,
      default: null,
    },
  },

  /**
   * The language the READER is actually reading in (DOCB-14351 follow-up).
   *
   * Not `$i18n.locale`. The application's language lives in Tolgee, and
   * `$i18n.locale` does not follow it — so the bilingual text the API composes
   * (`label`, `state_label`, `summary`, `explanation`, the evidence field
   * names) rendered ENGLISH for a reader who had switched the UI to German,
   * while this component's own chrome around it was correctly German. Measured
   * on dev 10.63.2: "Weg durch die Verarbeitung" above a diagram whose stages
   * read "Field Validation / blocked".
   *
   * Same probe-then-use shape as `IssueClusterCard`: `useTolgee` dereferences
   * the injection immediately and would throw wherever Tolgee is not installed
   * — component tests most of all, where the mocked `$i18n` is then still
   * honoured by the `locale` computed below.
   */
  setup() {
    const tolgee = inject('tolgeeContext', null)
      ? useTolgee(['language'])
      : null;
    const uiLanguage = computed(() => tolgee?.value?.getLanguage() || '');
    return { uiLanguage };
  },

  computed: {
    /**
     * Tolgee first, `$i18n` second, English last. Tolgee codes carry a region
     * (`en-us`, `pt-br`); the API keys its bilingual text on the bare language,
     * so only the first segment is used.
     */
    locale(): string {
      const raw = String(this.uiLanguage || this.$i18n?.locale || 'en');
      return raw.split('-')[0] || 'en';
    },

    sentence(): string {
      return (
        pickText(this.explanation, this.locale) ||
        this.$t('pipeline_why_no_explanation')
      );
    },

    stageLabel(): string {
      return pickText(this.blockingStage?.label, this.locale);
    },

    reasonLabel(): string {
      const raw = this.blockingStage?.reason_code || '';
      if (!raw) return '';
      const key = `touchless_reason_${raw.toLowerCase()}`;
      const translated = this.$t(key);
      return translated === key ? raw : translated;
    },

    durationLabel(): string {
      const ms = this.blockingStage?.duration_ms;
      if (typeof ms !== 'number' || ms < 0) return '';
      return `${ms} ms`;
    },

    /**
     * The evidence, as label/value rows.
     *
     * Labels come from the API's own `labels` map so a new evidence field
     * needs no Tolgee key and cannot render as a raw snake_case key. Values
     * are stringified here and nowhere else.
     */
    evidenceRows(): { key: string; label: string; value: string }[] {
      const evidence = this.blockingStage?.evidence;
      if (!evidence || !evidence.fields) return [];
      return Object.keys(evidence.fields)
        .sort()
        .map((key) => ({
          key,
          label: pickText(evidence.labels?.[key], this.locale) || key,
          value: this.renderValue(evidence.fields[key]),
        }));
    },

    missingFields(): string[] {
      const stage = this.blockingStage;
      if (!stage) return [];
      return stage.evidence?.missing?.length
        ? stage.evidence.missing
        : stage.evidence_expected || [];
    },

    missingEvidenceText(): string {
      const reason = this.blockingStage?.evidence_missing_reason;
      if (reason === 'no_stage_result') {
        return this.$t('pipeline_why_evidence_no_stage_result');
      }
      return this.$t('pipeline_why_evidence_not_instrumented');
    },

    analysis(): PipelineAnalysis | null {
      return this.blockingStage?.analysis || null;
    },

    isAiAnalysis(): boolean {
      return this.analysis?.source === 'llm';
    },

    analysisRows(): { key: string; label: string; value: string }[] {
      const analysis = this.analysis;
      if (!analysis) return [];
      const questions: { key: keyof PipelineAnalysis; label: string }[] = [
        { key: 'analysis', label: this.$t('pipeline_why_q_analysis') },
        {
          key: 'why_it_matters',
          label: this.$t('pipeline_why_q_why_it_matters'),
        },
        {
          key: 'expected_result',
          label: this.$t('pipeline_why_q_expected_result'),
        },
        { key: 'what_changes', label: this.$t('pipeline_why_q_what_changes') },
      ];
      // A question the source did not answer is DROPPED, not rendered empty:
      // a labelled blank invites the reader to read an answer into it.
      return questions
        .map((question) => ({
          key: String(question.key),
          label: question.label,
          value: pickText(
            analysis[question.key] as PipelineText | null,
            this.locale,
          ),
        }))
        .filter((row) => Boolean(row.value));
    },

    deterministicNote(): string {
      return this.$t('pipeline_why_deterministic_note');
    },
  },

  methods: {
    /** Values as text. Lists join, objects compact, everything else stringifies. */
    renderValue(value: unknown): string {
      if (value === null || value === undefined) return '—';
      if (Array.isArray(value)) {
        return value.map((item) => this.renderValue(item)).join(', ');
      }
      if (typeof value === 'object') {
        return Object.entries(value as Record<string, unknown>)
          .map(([key, item]) => `${key}: ${this.renderValue(item)}`)
          .join(', ');
      }
      return String(value);
    },
  },
});
</script>

